  border-radius: 12px !important;
  color: #f5f5f5 !important;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.6) !important;
  max-width: 380px;
  font-family: "Segoe UI", Roboto, sans-serif;
  font-size: 14px;
  line-height: 1.5;
