/* Popover header */
.popover-header {
  background: transparent !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15) !important;
  color: #e0e0e0 !important;
  font-weight: 600;
  padding: 10px 14px;
  font-size: 15px;
}

/* Popover body */
.popover-body {
  padding: 12px 16px;
