/* === TinyMCE Dark Modern Theme (Fix Header + Menubar) === */
.tox {
  --editor-bg: #1e1e2e;
  --editor-toolbar-bg: #252537;
  --editor-border: #333;
  --editor-text: #e0e0e0;
  --editor-hover: #3a3a52;
  --editor-accent: #6c63ff;

  background-color: var(--editor-bg) !important;
  color: var(--editor-text) !important;
  border: 1px solid var(--editor-border) !important;
  border-radius: 10px !important;
  overflow: hidden;
  backdrop-filter: blur(10px);
  box-shadow: 0 4px 20px rgba(0,0,0,0.6);
}

/* Header */
.tox .tox-editor-header {
  background-color: var(--editor-toolbar-bg) !important;
  border-bottom: 1px solid var(--editor-border) !important;
  color: var(--editor-text) !important;
}

/* Menubar */
.tox .tox-menubar {
  background-color: var(--editor-toolbar-bg) !important;
  border-bottom: 1px solid var(--editor-border) !important;
}

.tox .tox-menubar button {
  color: var(--editor-text) !important;
  background: transparent !important;
}

.tox .tox-menubar button:hover {
  background-color: var(--editor-hover) !important;
  color: var(--editor-accent) !important;
  border-radius: 6px;
}

/* Toolbar */
.tox .tox-toolbar,
.tox .tox-toolbar__overflow,
.tox .tox-toolbar__primary {
  background-color: var(--editor-toolbar-bg) !important;
  color: var(--editor-text) !important;
}

.tox .tox-toolbar__group button span svg {
  background: transparent !important;
  fill: var(--editor-text) !important;
  border: none !important;
}

.tox .tox-toolbar__group button:hover {
  background-color: var(--editor-hover) !important;
  fill: var(--editor-accent) !important;
  border-radius: 6px;
}

/* Pulsanti attivi */
.tox .tox-tbtn--enabled,
.tox .tox-tbtn--active {
  background-color: var(--editor-hover) !important;
  color: var(--editor-accent) !important;
}

/* Dropdown / menu */
.tox .tox-menu {
  background-color: var(--editor-toolbar-bg) !important;
  border: 1px solid var(--editor-border) !important;
  border-radius: 8px;
  box-shadow: 0 6px 15px rgba(0,0,0,0.5);
}

.tox .tox-collection__item {
  color: var(--editor-text) !important;
}
.tox .tox-collection__item--active,
.tox .tox-collection__item--enabled {
  background-color: var(--editor-hover) !important;
  color: var(--editor-accent) !important;
}

/* Area scrittura */
.tox-edit-area iframe {
  background-color: var(--editor-bg) !important;
  color: var(--editor-text) !important;
  border: none !important;
}

/* Statusbar */
.tox-statusbar {
  background: var(--editor-toolbar-bg) !important;
  border-top: 1px solid var(--editor-border) !important;
  color: var(--editor-text) !important;
}

.tox .tox-toolbar-overlord {
